// Passo 1: conferimos a entrada antes de calcular.
function somarAte(n) {
  if (typeof n !== 'number' || n < 0) {
    throw new Error('n precisa ser um número maior ou igual a 0');
  }

  // Passo 2: o pote começa vazio, FORA do laço.
  let soma = 0;

  // Passo 3: i vai de 1 até n, somando 1 a cada volta.
  for (let i = 1; i <= n; i++) {
    soma = soma + i; // joga o valor de i dentro do pote
  }

  // Passo 4: devolvemos o total acumulado.
  return soma;
}

console.log(somarAte(4)); // imprime: 10
